def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    # Find the color that forms the repeated horizontal and vertical grid lines.
    scores = {}
    for color in set(v for row in grid for v in row):
        scores[color] = (
            sum(sum(x == color for x in row) >= w - 2 for row in grid) +
            sum(sum(grid[r][c] == color for r in range(h)) >= h - 2
                for c in range(w))
        )
    frame = max(scores, key=scores.get)

    # Colored markers may replace a few frame cells at line intersections.
    rows = [r for r in range(h)
            if sum(x == frame for x in grid[r]) >= w - 2]
    cols = [c for c in range(w)
            if sum(grid[r][c] == frame for r in range(h)) >= h - 2]

    between = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in rows and c not in cols and grid[r][c] != frame
    )
    background = between.most_common(1)[0][0]

    out = [[background for _ in range(len(cols) - 1)]
           for _ in range(len(rows) - 1)]
    for i in range(len(rows) - 1):
        for j in range(len(cols) - 1):
            corners = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
            if corners[0] != frame and corners[0] != background and all(
                    x == corners[0] for x in corners):
                out[i][j] = corners[0]
    return out
